from llm_saea import Plan, benchmark, optimize

PLAN = Plan.from_dict({'surrogate': 'auto', 'operator': 'current_to_best', 'mutation': 0.8, 'crossover': 0.9, 'exploration': 0.5, 'local_fraction': 0.2, 'radius': 0.15, 'population': 30, 'generations': 6, 'reason': 'Stagnation (19 evals) with zero recent improvement and 76 evals remaining calls for more exploration rather than a tighter local focus. auto lets held-out RMSE pick RBF vs quadratic in this 10-D space with few initial samples. current_to_best balances convergence and diversity; raising exploration to 0.5 and mutation to 0.8 helps escape the plateau, while a moderate population/generations ratio keeps surrogate scoring cheap given the fixed budget.'})

def solve(problem, budget=100, seed=0):
    return optimize(problem, budget=budget, seed=seed, method='saea', plan=PLAN)

if __name__ == '__main__':
    result = solve(benchmark('sphere', 5))
    print({'best_y': result.best_y, 'best_x': result.best_x.tolist()})
